import { ApiProperty } from '@nestjs/swagger';
import { IsNotEmpty, IsOptional, IsString } from 'class-validator';

/**
 * The value used on the `upperBound` of a tier to indicate that the tier has no upper limit.
 */
export const INFINITE_UPPER_BOUND = 'inf';

/**
 * The maximum number of digits of precision allowed after the decimal place for any price field.
 */
const MAX_PRICE_DECIMAL_PLACES = 8;

const isNumericString = (value: unknown): boolean => {
    if (typeof value !== 'string' || value.trim() === '') {
        return false;
    }
    return !isNaN(Number(value)) && !isNaN(parseFloat(value));
};

/**
 * @author Enterprise
 *
 * @Class
 * A single volume based pricing tier of a dimension.
 * Tiers allow a dimension to be billed at a different unit price depending on the amount of usage consumed.
 * For instance the first 1,000 API calls may be free, the next 9,000 may cost $0.01 each,
 * and every API call afterwards may cost $0.005 each.
 */
export class Tier {
    /**
     * The position of the tier relative to the other tiers of the dimension.
     * Tiers are ordered by the numeric value of this field, the lowest position is the first tier.
     * Numerical values are represented as strings to avoid precision loss.
     * <br><br>
     * Example `"1"`
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'tierPosition',
        description:
            'The position of the tier relative to the other tiers of the dimension. Tiers are ordered by the numeric value of this field.',
        example: '1',
        type: String,
        required: true,
    })
    public tierPosition: string;

    /**
     * The inclusive upper bound of the tier expressed in the consumption unit of the dimension.
     * The lower bound of a tier is the upper bound of the preceding tier.
     * The last tier may use `"inf"` to indicate that the tier has no upper limit.
     * Numerical values are represented as strings to avoid precision loss.
     * <br><br>
     * Example `"1000"`, `"inf"`
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'upperBound',
        description:
            'The inclusive upper bound of the tier. Must be a numeric string or "inf", "inf" is only valid on the last tier.',
        examples: ['1000', 'inf'],
        type: String,
        required: true,
    })
    public upperBound: string;

    /**
     * An optional friendly, human-readable name for the tier.
     * When set it is appended to the name of the line item generated for the tier on the invoice.
     * <br><br>
     * Example `"First 1,000 API Calls"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({
        name: 'tierName',
        description:
            'An optional friendly name of the tier, when set it is appended to the name of the invoice line item generated for the tier.',
        example: 'First 1,000 API Calls',
        type: String,
        required: false,
    })
    public tierName?: string;

    /**
     * The unit price of the usage which falls inside of the tier.
     * Numerical values are represented as strings to avoid precision loss.
     * The field is required for every tier except for the first one,
     * omitting it on the first tier makes the first tier a free tier.
     * <br><br>
     * Example `"0.05"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({
        name: 'unitPrice',
        description:
            'The unit price of the usage which falls inside of the tier. Required for every tier except the first one, when omitted on the first tier the tier is free.',
        example: '0.05',
        type: String,
        required: false,
    })
    public unitPrice?: string;

    constructor(tier?: Tier) {
        if (tier) {
            const { tierPosition, upperBound, tierName, unitPrice } = tier;
            this.tierPosition = tierPosition;
            this.upperBound = upperBound;
            if (tierName !== undefined) {
                this.tierName = tierName;
            }
            if (unitPrice !== undefined) {
                this.unitPrice = unitPrice;
            }
        }
    }

    /**
     * Determines if the given upper bound represents an unbounded tier.
     */
    public static isInfiniteUpperBound(upperBound: string): boolean {
        return typeof upperBound === 'string' && upperBound.trim().toLowerCase() === INFINITE_UPPER_BOUND;
    }

    /**
     * The numeric representation of the upper bound of a tier, unbounded tiers return `Infinity`.
     */
    public static upperBoundToNumber(upperBound: string): number {
        return Tier.isInfiniteUpperBound(upperBound) ? Infinity : parseFloat(upperBound);
    }

    /**
     * Sorts the tiers by the numeric value of their `tierPosition` in ascending order without mutating the input.
     */
    public static sortTiers(tiers: Tier[]): Tier[] {
        return [...tiers].sort((a, b) => parseFloat(a.tierPosition) - parseFloat(b.tierPosition));
    }

    /**
     * Allocates the total amount of usage across the tiers of a dimension.
     * The bounds of a tier are inclusive, the lower bound of a tier is the upper bound of the preceding tier.
     * Only the tiers which have consumed usage are returned.
     */
    public static allocateUsage({ tiers, totalUsage }: { tiers: Tier[]; totalUsage: number }): Array<{
        tier: Tier;
        usage: number;
    }> {
        if (!tiers?.length || !(totalUsage > 0)) {
            return [];
        }
        const allocations: Array<{ tier: Tier; usage: number }> = [];
        let lowerBound = 0;
        for (const tier of Tier.sortTiers(tiers)) {
            const upperBound = Tier.upperBoundToNumber(tier.upperBound);
            const usageInTier = Math.min(totalUsage, upperBound) - lowerBound;
            if (usageInTier > 0) {
                allocations.push({ tier, usage: usageInTier });
            }
            lowerBound = upperBound;
            if (totalUsage <= upperBound) {
                break;
            }
        }
        return allocations;
    }

    /**
     * The unit price of a tier, tiers without a unit price are free.
     */
    public static tierPrice(tier: Tier): string {
        return tier?.unitPrice ? tier.unitPrice : '0';
    }

    /**
     * Validates the tiers of a dimension against the rest of the dimension configuration.
     * Returns the list of the validation errors, an empty list means that the tiers are valid.
     */
    public static validateTiers({
        tiers,
        usageIncrement,
        usageEntitlement,
        consumptionPrice,
        overageAllowed,
    }: {
        tiers?: Tier[] | null;
        usageIncrement?: string | number;
        usageEntitlement?: number | 'inf' | null;
        consumptionPrice?: string | null;
        overageAllowed?: string | boolean | null;
    }): string[] {
        if (tiers === undefined || tiers === null) {
            return [];
        }
        const errors: string[] = [];
        if (!Array.isArray(tiers) || !tiers.length) {
            return ['tiers: must be a non empty array of tiers'];
        }
        if (usageEntitlement !== undefined && usageEntitlement !== null) {
            errors.push('tiers: cannot be set on a dimension which has a usageEntitlement');
        }
        if (consumptionPrice !== undefined && consumptionPrice !== null && `${consumptionPrice}` !== '') {
            errors.push('tiers: cannot be set on a dimension which has a consumptionPrice');
        }
        if (overageAllowed === true || `${overageAllowed}` === 'true') {
            errors.push('tiers: cannot be set on a dimension which has overageAllowed set to true');
        }

        tiers.forEach((tier) => {
            if (!tier || typeof tier !== 'object') {
                errors.push('tiers: every tier must be an object containing a tierPosition and an upperBound');
                return;
            }
            const { tierPosition, upperBound, unitPrice } = tier;
            if (!isNumericString(tierPosition)) {
                errors.push(`tiers: tierPosition: ${tierPosition} must be a numeric string`);
            }
            if (!Tier.isInfiniteUpperBound(upperBound) && !isNumericString(upperBound)) {
                errors.push(`tiers: upperBound: ${upperBound} must be a numeric string or "inf"`);
            } else if (!Tier.isInfiniteUpperBound(upperBound) && parseFloat(upperBound) <= 0) {
                errors.push(`tiers: upperBound: ${upperBound} must be greater than 0`);
            }
            if (unitPrice !== undefined && unitPrice !== null) {
                if (!isNumericString(unitPrice) || parseFloat(unitPrice) < 0) {
                    errors.push(`tiers: unitPrice: ${unitPrice} must be a positive numeric string`);
                } else if (unitPrice.split('.')[1]?.length > MAX_PRICE_DECIMAL_PLACES) {
                    errors.push(
                        `tiers: unitPrice: ${unitPrice} cannot have more than ${MAX_PRICE_DECIMAL_PLACES} digits of precision after decimal place`,
                    );
                }
            }
        });
        if (errors.length) {
            // The ordering of the tiers can only be checked once every tier is known to be well formed
            return errors;
        }

        const positions = tiers.map(({ tierPosition }) => parseFloat(tierPosition));
        if (new Set(positions).size !== positions.length) {
            errors.push('tiers: tierPosition must be unique across the tiers of a dimension');
            return errors;
        }

        const increment = usageIncrement !== undefined && usageIncrement !== null ? parseFloat(`${usageIncrement}`) : 1;
        const sortedTiers = Tier.sortTiers(tiers);
        let previousUpperBound = 0;
        sortedTiers.forEach((tier, index) => {
            const { upperBound, unitPrice } = tier;
            const isLastTier = index === sortedTiers.length - 1;
            if (Tier.isInfiniteUpperBound(upperBound)) {
                if (!isLastTier) {
                    errors.push('tiers: only the tier with the highest tierPosition can have an upperBound of "inf"');
                }
            } else {
                const numericUpperBound = parseFloat(upperBound);
                if (numericUpperBound <= previousUpperBound) {
                    errors.push(
                        `tiers: upperBound: ${upperBound} must be greater than the upperBound of the preceding tier: ${previousUpperBound}`,
                    );
                }
                if (increment > 0 && numericUpperBound % increment !== 0) {
                    errors.push(
                        `tiers: upperBound: ${upperBound} must be a multiple of the usageIncrement: ${increment}`,
                    );
                }
                previousUpperBound = numericUpperBound;
            }
            if (index > 0 && (unitPrice === undefined || unitPrice === null)) {
                errors.push(
                    `tiers: unitPrice is required for every tier except the first one, tierPosition: ${tier.tierPosition} is missing a unitPrice`,
                );
            }
        });

        return errors;
    }
}

import { Injectable } from '@nestjs/common';
import {
