/**
 * @author Enterprise
 *
 * Validates the volume based pricing tiers of a dimension.
 * The rules which are applied to the tiers are documented on {@link Tier.validateTiers}
 */
@ValidatorConstraint({ name: 'ValidTiers', async: false })
@Injectable()
export class ValidTiersRule implements ValidatorConstraintInterface {
    validate(tiers: Tier[], args: ValidationArguments) {
        const { usageIncrement, usageEntitlement, consumptionPrice, overageAllowed } = (args?.object ??
            {}) as CreateDimensionDto;
        return !Tier.validateTiers({ tiers, usageIncrement, usageEntitlement, consumptionPrice, overageAllowed })
            .length;
    }

    defaultMessage(args: ValidationArguments) {
        const { tiers, usageIncrement, usageEntitlement, consumptionPrice, overageAllowed } = (args?.object ??
            {}) as CreateDimensionDto;
        return Tier.validateTiers({
            tiers,
            usageIncrement,
            usageEntitlement,
            consumptionPrice,
            overageAllowed,
        }).join('. ');
    }
}

export function ValidTiers(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidTiers',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: ValidTiersRule,
        });
    };
}

