import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    CreateDimensionDto,
    overageAllowedEnum,
    roundingEnum,
} from './create-dimension.dto.js';
import { Tier } from './tier.dto.js';

const baseDimension = {
    dimensionName: 'API Call',
    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
    usageIncrement: '1',
    rounding: roundingEnum.ceiling,
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
};

const validTiers = [
    { tierPosition: '1', upperBound: '1000', tierName: 'Free Tier' },
    { tierPosition: '2', upperBound: '10000', unitPrice: '0.05' },
    { tierPosition: '3', upperBound: 'inf', unitPrice: '0.03' },
];

const validateDimension = async (dimension: Record<string, unknown>) => {
    const errors = await validate(plainToInstance(CreateDimensionDto, dimension));
    return errors.reduce((acc, error) => {
        Object.values(error.constraints ?? {}).forEach((message) => acc.push(message));
        return acc;
    }, [] as string[]);
};

describe('Tier', () => {
    describe('validateTiers', () => {
        test('Dimensions without tiers are always valid', () => {
            expect(Tier.validateTiers({ usageIncrement: '1', consumptionPrice: '0.5' })).toEqual([]);
            expect(Tier.validateTiers({ tiers: null, usageIncrement: '1', consumptionPrice: '0.5' })).toEqual([]);
        });
        test('A well formed collection of tiers is valid', () => {
            expect(Tier.validateTiers({ tiers: validTiers, usageIncrement: '1' })).toEqual([]);
        });
        test('Tiers must be a non empty array', () => {
            expect(Tier.validateTiers({ tiers: [], usageIncrement: '1' })).toHaveLength(1);
        });
        test('Only the last tier can be unbounded', () => {
            const errors = Tier.validateTiers({
                tiers: [
                    { tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: '10000', unitPrice: '0.03' },
                ],
                usageIncrement: '1',
            });
            expect(errors).toEqual([expect.stringContaining('inf')]);
        });
        test('Upper bounds must increase without overlapping', () => {
            const errors = Tier.validateTiers({
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: '1000', unitPrice: '0.05' },
                ],
                usageIncrement: '1',
            });
            expect(errors).toEqual([expect.stringContaining('must be greater than the upperBound')]);
        });
        test('Upper bounds are checked in tierPosition order and not in the order they are given in', () => {
            expect(
                Tier.validateTiers({
                    tiers: [
                        { tierPosition: '3', upperBound: 'inf', unitPrice: '0.03' },
                        { tierPosition: '1', upperBound: '1000' },
                        { tierPosition: '2', upperBound: '10000', unitPrice: '0.05' },
                    ],
                    usageIncrement: '1',
                }),
            ).toEqual([]);
        });
        test('Upper bounds must align with the usage increment', () => {
            const errors = Tier.validateTiers({
                tiers: [
                    { tierPosition: '1', upperBound: '1500' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.05' },
                ],
                usageIncrement: '1000',
            });
            expect(errors).toEqual([expect.stringContaining('must be a multiple of the usageIncrement')]);
        });
        test('Every tier apart from the first one requires a unit price', () => {
            const errors = Tier.validateTiers({
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: 'inf' },
                ],
                usageIncrement: '1',
            });
            expect(errors).toEqual([expect.stringContaining('unitPrice is required')]);
        });
        test('Tier positions must be unique numeric strings', () => {
            expect(
                Tier.validateTiers({
                    tiers: [
                        { tierPosition: '1', upperBound: '1000' },
                        { tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' },
                    ],
                    usageIncrement: '1',
                }),
            ).toEqual([expect.stringContaining('must be unique')]);
            expect(
                Tier.validateTiers({
                    tiers: [{ tierPosition: 'first', upperBound: 'inf' }],
                    usageIncrement: '1',
                }),
            ).toEqual([expect.stringContaining('must be a numeric string')]);
        });
        test('Unit prices cannot have more than 8 digits of precision', () => {
            expect(
                Tier.validateTiers({
                    tiers: [
                        { tierPosition: '1', upperBound: '1000' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.000000004' },
                    ],
                    usageIncrement: '1',
                }),
            ).toEqual([expect.stringContaining('digits of precision')]);
        });
        test('Tiers are mutually exclusive with entitlements, consumption price and overage', () => {
            expect(
                Tier.validateTiers({ tiers: validTiers, usageIncrement: '1', usageEntitlement: 1000 }),
            ).toEqual([expect.stringContaining('usageEntitlement')]);
            expect(Tier.validateTiers({ tiers: validTiers, usageIncrement: '1', consumptionPrice: '0.5' })).toEqual([
                expect.stringContaining('consumptionPrice'),
            ]);
            expect(
                Tier.validateTiers({
                    tiers: validTiers,
                    usageIncrement: '1',
                    overageAllowed: overageAllowedEnum.true,
                }),
            ).toEqual([expect.stringContaining('overageAllowed')]);
            expect(
                Tier.validateTiers({
                    tiers: validTiers,
                    usageIncrement: '1',
                    overageAllowed: overageAllowedEnum.false,
                }),
            ).toEqual([]);
        });
    });

    describe('allocateUsage', () => {
        test('Usage is allocated across the inclusive bounds of the tiers', () => {
            expect(Tier.allocateUsage({ tiers: validTiers, totalUsage: 15000 })).toEqual([
                { tier: validTiers[0], usage: 1000 },
                { tier: validTiers[1], usage: 9000 },
                { tier: validTiers[2], usage: 5000 },
            ]);
        });
        test('Only the tiers which have consumed usage are returned', () => {
            expect(Tier.allocateUsage({ tiers: validTiers, totalUsage: 1000 })).toEqual([
                { tier: validTiers[0], usage: 1000 },
            ]);
            expect(Tier.allocateUsage({ tiers: validTiers, totalUsage: 1001 })).toEqual([
                { tier: validTiers[0], usage: 1000 },
                { tier: validTiers[1], usage: 1 },
            ]);
        });
        test('Tiers are allocated in tierPosition order and not in the order they are given in', () => {
            const unorderedTiers = [validTiers[2], validTiers[0], validTiers[1]];
            expect(Tier.allocateUsage({ tiers: unorderedTiers, totalUsage: 10001 })).toEqual([
                { tier: validTiers[0], usage: 1000 },
                { tier: validTiers[1], usage: 9000 },
                { tier: validTiers[2], usage: 1 },
            ]);
        });
        test('No usage means no allocation', () => {
            expect(Tier.allocateUsage({ tiers: validTiers, totalUsage: 0 })).toEqual([]);
            expect(Tier.allocateUsage({ tiers: undefined, totalUsage: 100 })).toEqual([]);
        });
    });

    describe('CreateDimensionDto validation', () => {
        test('A tiered dimension without a consumption price is valid', async () => {
            expect(await validateDimension({ ...baseDimension, tiers: validTiers })).toEqual([]);
        });
        test('A tiered dimension with a consumption price is invalid', async () => {
            expect(
                await validateDimension({ ...baseDimension, consumptionPrice: '0.5', tiers: validTiers }),
            ).not.toEqual([]);
        });
        test('A tiered dimension with an entitlement is invalid', async () => {
            expect(await validateDimension({ ...baseDimension, usageEntitlement: 100, tiers: validTiers })).not.toEqual(
                [],
            );
        });
        test('A dimension with misaligned tiers is invalid', async () => {
            expect(
                await validateDimension({
                    ...baseDimension,
                    usageIncrement: '1000',
                    tiers: [
                        { tierPosition: '1', upperBound: '1500' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.05' },
                    ],
                }),
            ).not.toEqual([]);
        });
        test('A non tiered dimension still requires a consumption price', async () => {
            expect(await validateDimension({ ...baseDimension })).not.toEqual([]);
            expect(await validateDimension({ ...baseDimension, consumptionPrice: '0.5' })).toEqual([]);
        });
    });
});

