import { Point } from '@influxdata/influxdb-client';
import { InfluxService } from '../../influx/influx.service.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    CreateDimensionDto,
    roundingEnum,
} from '../dto/create-dimension.dto.js';
import { Tier } from '../dto/tier.dto.js';
import { DimensionEntity, numericalType } from './dimensions.entity.js';
import { SampleType } from '../dto/create-dimension.dto.js';

const influxService = { getPoint: (measurement: string) => new Point(measurement) } as InfluxService;

const tiers: Tier[] = [
    { tierPosition: '1', upperBound: '1000', tierName: 'Free Tier' },
    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.05' },
];

const dimensionEntityInput = (numericalOverrides: Record<string, unknown>): DimensionEntity =>
    ({
        dimensionId: 'fakeDimensionId',
        businessID: 'fakeBusinessID',
        typeofDimension: 'numerical',
        dimensionName: 'API Call',
        numerical: {
            numericalType: numericalType.int,
            dimensionUnit: countBasedUnits['count-based'],
            dimensionUnitType: 'count',
            aggregationInterval: aggregationInterval.hour,
            aggregationMethod: aggregationMethod.sum,
            sampleType: SampleType.gauge,
            usageIncrement: 1,
            rounding: roundingEnum.ceiling,
            priceSegments: [{ lowerLimit: '0', upperLimit: 'inf' }],
            ...numericalOverrides,
        },
    }) as unknown as DimensionEntity;

/**
 * Influx only stores strings, this simulates the row which comes back from the ledger for a written point.
 */
const pointToDbModel = (point: Point, dimensionName: string) => {
    const [, tags] = point.toLineProtocol().split(',', 1).length
        ? [undefined, point.toLineProtocol()]
        : [undefined, ''];
    return { tags, dimensionName };
};

describe('DimensionEntity tiers', () => {
    test('Tiers are written to the ledger and read back as the same tier objects', () => {
        const entity = new DimensionEntity(dimensionEntityInput({ tiers }));
        const point = DimensionEntity.transformer(entity, influxService);
        const lineProtocol = point.toLineProtocol();
        expect(lineProtocol).toContain('tiers=');

        // The ledger returns every tag of the point as a string keyed by the tag name
        const dbModel = {
            _value: 'API Call',
            dimensionId: 'fakeDimensionId',
            businessID: 'fakeBusinessID',
            typeofDimension: 'numerical',
            dimensionUnit: countBasedUnits['count-based'],
            dimensionUnitType: 'count',
            aggregationInterval: aggregationInterval.hour,
            aggregationMethod: aggregationMethod.sum,
            sampleType: SampleType.gauge,
            usageIncrement: '1',
            rounding: roundingEnum.ceiling,
            priceSegments: JSON.stringify([{ lowerLimit: '0', upperLimit: 'inf' }]),
            tiers: JSON.stringify(tiers),
        };
        const readEntity = DimensionEntity.dbModelToEntity(dbModel);
        expect(readEntity.numerical.tiers).toEqual(tiers);

        const readDto = new CreateDimensionDto(readEntity);
        expect(readDto.tiers).toEqual(tiers);
        expect(readDto.consumptionPrice).toBeUndefined();
    });

    test('Dimensions without tiers do not write a tiers tag and read back without tiers', () => {
        const entity = new DimensionEntity(
            dimensionEntityInput({ priceSegments: [{ lowerLimit: '0', upperLimit: 'inf', price: '0.5' }] }),
        );
        const point = DimensionEntity.transformer(entity, influxService);
        expect(point.toLineProtocol()).not.toContain('tiers=');

        const readEntity = DimensionEntity.dbModelToEntity({
            _value: 'API Call',
            dimensionId: 'fakeDimensionId',
            businessID: 'fakeBusinessID',
            typeofDimension: 'numerical',
            dimensionUnit: countBasedUnits['count-based'],
            dimensionUnitType: 'count',
            aggregationInterval: aggregationInterval.hour,
            aggregationMethod: aggregationMethod.sum,
            sampleType: SampleType.gauge,
            usageIncrement: '1',
            rounding: roundingEnum.ceiling,
            priceSegments: JSON.stringify([{ lowerLimit: '0', upperLimit: 'inf', price: '0.5' }]),
        });
        expect(readEntity.numerical.tiers).toBeUndefined();
        const readDto = new CreateDimensionDto(readEntity);
        expect(readDto.tiers).toBeUndefined();
        expect(readDto.consumptionPrice).toEqual('0.5');
    });
});

