import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerUsageData } from '../../customer/dto/read-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    roundingEnum,
    timeBasedUnits,
} from '../../dimensions/dto/create-dimension.dto.js';
import { ReadDimensionResponseData } from '../../dimensions/dto/read-dimension.dto.js';
import { Tier } from '../../dimensions/dto/tier.dto.js';
import { InvoiceLineItem, InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Offering } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';

jest.mock('../../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 0.91),
    },
}));

const fakeBusinessID = 'fakeBusinessID';
const fakeCustomerID = 'fakeCustomerID';
const fakeSettings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;

describe('Volume based pricing tiers', () => {
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;

    const tiers: Tier[] = [
        { tierPosition: '1', upperBound: '1000', tierName: 'First 1000' },
        { tierPosition: '2', upperBound: '10000', unitPrice: '0.05', tierName: 'Next 9000' },
        { tierPosition: '3', upperBound: 'inf', unitPrice: '0.03' },
    ];

    const tieredDimension = (overrides: Partial<ReadDimensionResponseData> = {}): ReadDimensionResponseData =>
        ({
            dimensionId: '123',
            dimensionName: 'fakeDimensionName',
            aggregationInterval: aggregationInterval.month,
            aggregationMethod: aggregationMethod.sum,
            rounding: roundingEnum.floor,
            usageIncrement: '1',
            consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
            tiers,
            ...overrides,
        }) as ReadDimensionResponseData;

    const usageOffering = (dimensions: ReadDimensionResponseData[]): ReadOfferingResponseData => ({
        offeringId: '123',
        offeringName: 'foobar',
        offeringType: OfferingType.usageBased,
        currency: SupportedCurrencies.USD,
        billingCycle: ValidBillingCycles.monthly,
        dimensions,
    });

    const mockUsage = (value: string) => {
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
            async () =>
                ({
                    message: 'fake',
                    data: [
                        {
                            dimensionId: '123',
                            usage: [{ startTime: new Date().toISOString(), endTime: new Date().toISOString(), value }],
                        },
                    ],
                }) as ReadCustomerUsageData,
        );
    };

    const getLineItems = async ({
        dimension,
        currency = SupportedCurrencies.USD,
        settings = fakeSettings,
        negative = false,
    }: {
        dimension: ReadDimensionResponseData;
        currency?: SupportedCurrencies;
        settings?: ReadSettingsResponseData;
        negative?: boolean;
    }) => {
        const offering = usageOffering([dimension]);
        const customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            businessID: fakeBusinessID,
            email: 'fakeEmail',
            currency,
            offering,
        } as ReadCustomerResponseData;
        jest.spyOn(customerService, 'findOne').mockImplementation(async () => ({
            data: [{ ...customer, invoices: [] }],
            message: 'test',
        }));
        const lineItems = await Offering.getLineItemsForUsage({
            customerService,
            customer,
            startDate: new Date('2023-07-01'),
            endDate: new Date('2023-07-31'),
            customerId: fakeCustomerID,
            businessID: fakeBusinessID,
            dimensions: [dimension],
            negative,
            lineItems: new InvoiceLineItems(),
            offeringInstance: Offering.getInstance(
                offering,
                fakeCustomerID,
                fakeBusinessID,
                invoicesService,
                settings,
                schedulerService,
                customerService,
            ),
        });
        return lineItems.getLineItems();
    };

    beforeAll(() => {
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
    });
    afterEach(() => {
        jest.clearAllMocks();
    });

    test('A distinct line item is created for every consumed tier', async () => {
        mockUsage('15000');
        expect(await getLineItems({ dimension: tieredDimension() })).toEqual([
            new InvoiceLineItem('fakeDimensionName - foobar - First 1000', 1000, 0),
            new InvoiceLineItem('fakeDimensionName - foobar - Next 9000', 9000, 0.05),
            new InvoiceLineItem('fakeDimensionName - foobar', 5000, 0.03),
        ]);
    });

    test('Only the consumed tiers produce line items', async () => {
        mockUsage('1500');
        expect(await getLineItems({ dimension: tieredDimension() })).toEqual([
            new InvoiceLineItem('fakeDimensionName - foobar - First 1000', 1000, 0),
            new InvoiceLineItem('fakeDimensionName - foobar - Next 9000', 500, 0.05),
        ]);
    });

    test('Tiers are ordered by the numeric value of the tier position', async () => {
        mockUsage('15000');
        expect(
            await getLineItems({ dimension: tieredDimension({ tiers: [tiers[2], tiers[0], tiers[1]] }) }),
        ).toEqual([
            new InvoiceLineItem('fakeDimensionName - foobar - First 1000', 1000, 0),
            new InvoiceLineItem('fakeDimensionName - foobar - Next 9000', 9000, 0.05),
            new InvoiceLineItem('fakeDimensionName - foobar', 5000, 0.03),
        ]);
    });

    test('The quantity of every tier is divided by the usage increment', async () => {
        mockUsage('90000');
        expect(
            await getLineItems({
                dimension: tieredDimension({
                    usageIncrement: '3600',
                    consumptionUnit: { unit: timeBasedUnits.second, type: 'time' },
                    tiers: [
                        { tierPosition: '1', upperBound: '36000', unitPrice: '1' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.5' },
                    ],
                }),
            }),
        ).toEqual([
            new InvoiceLineItem('fakeDimensionName - Hour - foobar', 10, 1),
            new InvoiceLineItem('fakeDimensionName - Hour - foobar', 15, 0.5),
        ]);
    });

    test('The precision of the unit price of a tier is preserved when converting currency', async () => {
        mockUsage('2000');
        expect(
            await getLineItems({
                currency: SupportedCurrencies.EUR,
                dimension: tieredDimension({
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', unitPrice: '1.23456789' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '2' },
                    ],
                }),
            }),
        ).toEqual([
            // 1.12345678 = 0.91 * 1.23456789, the exchange rate of the mocked analytics service is 0.91
            new InvoiceLineItem('fakeDimensionName - foobar', 1000, 1.12345678),
            new InvoiceLineItem('fakeDimensionName - foobar', 1000, 1.82),
        ]);
    });

    test('A free first tier is hidden when free dimensions are hidden on the invoice', async () => {
        mockUsage('1500');
        expect(
            await getLineItems({
                dimension: tieredDimension(),
                settings: { freeDimensionOnInvoice: FreeDimensionOnInvoice.hide } as ReadSettingsResponseData,
            }),
        ).toEqual([new InvoiceLineItem('fakeDimensionName - foobar - Next 9000', 500, 0.05)]);
    });

    test('Tiered line items are negated during a free trial', async () => {
        mockUsage('1500');
        expect(await getLineItems({ dimension: tieredDimension(), negative: true })).toEqual([
            new InvoiceLineItem('fakeDimensionName - foobar - First 1000 - Free Trial Credit', -1000, 0),
            new InvoiceLineItem('fakeDimensionName - foobar - Next 9000 - Free Trial Credit', -500, 0.05),
        ]);
    });

    test('Dimensions without tiers keep producing a single line item', async () => {
        mockUsage('1500');
        expect(
            await getLineItems({ dimension: tieredDimension({ tiers: undefined, consumptionPrice: '0.5' }) }),
        ).toEqual([new InvoiceLineItem('fakeDimensionName - foobar', 1500, 0.5)]);
    });
});

