            Tier.allocateUsage({ tiers, totalUsage }).forEach(({ tier, usage }) => {
                // Handle currency conversion
                const unitCost = Offering.convertPriceToCurrency({
                    price: Tier.tierPrice(tier),
                    exchangeRate,
                });
                const shouldDisplayLineItem = Billing.determineIfLineItemShown({
                    Offering: offeringInstance,
                    dimension,
                    totalUsage: usage,
                    unitCost,
                    freeDimensionOnInvoice: offeringInstance.settings?.freeDimensionOnInvoice,
                });
                if (shouldDisplayLineItem) {
                    const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
                        total: usage,
                        dimensionType: type,
                        dimensionId,
                        dimensionName: dimension.dimensionName,
                        offeringName: offeringInstance.offeringName,
                        usageIncrement: parseInt(usageIncrement),
                        dimensionUnit: unit,
                        negative,
                        tierName: tier.tierName,
                    });
                    lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
                }
            });
            return;
        }
        const unitCost = Offering.convertPriceToCurrency({
            price: dimension.consumptionPrice,
            exchangeRate,
        });
        const shouldDisplayLineItem = Billing.determineIfLineItemShown({
            Offering: offeringInstance,
            dimension,
            totalUsage: dimensionTotals[dimensionId] as number,
            unitCost,
            freeDimensionOnInvoice: offeringInstance.settings?.freeDimensionOnInvoice,
        });
        if (shouldDisplayLineItem) {
            // Handle currency conversion

            const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
                total: dimensionTotals[dimensionId],
                dimensionType: type,
                dimensionId,
                dimensionName: dimension.dimensionName,
                offeringName: offeringInstance.offeringName,
                usageIncrement: parseInt(usageIncrement),
                dimensionUnit: unit,
                negative,
            });
            lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
        }
    });

    return lineItems;
}
/**
 * Converts a price expressed as a string in USD to the currency of the invoice while preserving the precision of the price.
 */
static convertPriceToCurrency({ price, exchangeRate }: { price: string; exchangeRate: number }): number {
    const numericPrice = parseFloat(price);
    const decimals = Offering.getDecimalsForNumber(numericPrice);
    return Number((numericPrice * exchangeRate).toFixed(decimals === 0 ? 2 : decimals));
}

